 * The shape returned by {@link parseCompletionArgs}.
 */
export interface CompletionArgs {
  /** All shell tokens the user has typed (excluding the `nx` script name). */
  tokens: string[];
  /** The last token — the partial string currently being completed. */
  current: string;
  /** The second-to-last token, or '' if only one token has been typed. */
  previousToken: string;
}

/**
 * Parses a `process.argv`-style array for shell completion.
 *
 * The first two entries (the node runtime and the nx binary path) are stripped,
 * then a leading `nx` script-name token is stripped if present. The remaining
 * entries are the user-supplied shell tokens.
 *
 * Returns `null` if no user-supplied tokens remain after stripping.
 */
export function parseCompletionArgs(argv: string[]): CompletionArgs | null {
  // Strip the node runtime and the nx binary path.
  let tokens = argv.slice(2);

  // Strip a leading `nx` script-name token if the shell passed it through.
  if (tokens[0] === 'nx') {
    tokens = tokens.slice(1);
  }

  if (tokens.length === 0) {
    return null;
  }

  const current = tokens[tokens.length - 1];
  const previousToken = tokens.length > 1 ? tokens[tokens.length - 2] : '';

  return { tokens, current, previousToken };
}
