export const DESC_SEPARATOR = '\t';

const YARGS_STRING_MARKER = '__yargsString__:';

/**
 * Sanitizes a command description for use in shell completion output.
 *
 * - Strips the yargs i18n marker prefix (`__yargsString__:`) from the start.
 * - Collapses any literal TAB characters in the remaining string to spaces so
 *   they do not break the value/description split.
 * - Returns '' for undefined or empty input.
 *
 * Colons that appear in the rest of the description are left untouched.
 */
export function formatDescription(description: string | undefined): string {
  if (!description) {
    return '';
  }

  let result = description;
  if (result.startsWith(YARGS_STRING_MARKER)) {
    result = result.slice(YARGS_STRING_MARKER.length);
  }

  return result.replace(/\t/g, ' ');
}

