import { workspaceRoot } from '../../utils/workspace-root';

/**
 * Reads the cached project graph, returning `null` when it is unavailable
 * (e.g. it has not been computed yet). All providers degrade gracefully to an
 * empty result rather than throwing during shell completion.
 */
function safeReadProjectGraph(): ProjectGraph | null {
  try {
    return readCachedProjectGraph();
  } catch {
    return null;
  }
}

/**
 * Returns all project names from the cached project graph that start with the
 * given prefix. Returns [] if the project graph is unavailable.
 */
export function getProjectNameCompletions(prefix: string): string[] {
  const graph = safeReadProjectGraph();
  if (!graph) {
    return [];
  }
  return Object.keys(graph.nodes).filter((name) => name.startsWith(prefix));
}

/**
 * Returns project names that start with the given prefix AND have a target
 * matching the given target name. Returns [] if no projects match, the target
 * does not exist, or the graph is unavailable.
 */
export function getProjectNamesWithTarget(
  prefix: string,
  target: string
): string[] {
  const graph = safeReadProjectGraph();
  if (!graph) {
    return [];
  }
  return Object.keys(graph.nodes).filter((name) => {
    if (!name.startsWith(prefix)) {
      return false;
    }
    const targets = graph.nodes[name]?.data?.targets;
    return !!targets && !!targets[target];
  });
}

/**
 * Returns unique target names across all workspace projects that start with the
 * given prefix. Returns [] if the graph is unavailable.
 */
export function getTargetNameCompletions(prefix: string): string[] {
  const graph = safeReadProjectGraph();
  if (!graph) {
    return [];
  }
  const targetNames = new Set<string>();
  for (const node of Object.values(graph.nodes)) {
    for (const targetName of Object.keys(node.data?.targets ?? {})) {
      if (targetName.startsWith(prefix)) {
        targetNames.add(targetName);
      }
    }
  }
  return Array.from(targetNames);
}

/**
 * Returns target names for a specific project that start with the given prefix.
 * If the project name does not exist in the graph, falls back to all workspace
 * target names (to support partial project-name typing scenarios such as
 * `project:t<TAB>`). Returns [] if the graph is unavailable.
 */
export function getTargetNamesForProject(
  prefix: string,
  projectName: string
): string[] {
  const graph = safeReadProjectGraph();
  if (!graph) {
    return [];
  }
  const node = graph.nodes[projectName];
  if (!node) {
    return getTargetNameCompletions(prefix);
  }
  return Object.keys(node.data?.targets ?? {}).filter((name) =>
    name.startsWith(prefix)
  );
}

/**
 * Two-stage completion for `project:target` tokens.
 *
 * Stage 1 (no colon in `current`): returns matching project names each suffixed
 * with `:`.
 *
 * Stage 2 (colon present): returns `projectName:targetName` candidates matching
 * the portion after the colon, using all workspace targets if the project name
 * is unknown.
 */
export function completeProjectTarget(current: string): string[] {
  const colonIndex = current.indexOf(':');
  if (colonIndex === -1) {
    return getProjectNameCompletions(current).map((name) => `${name}:`);
  }

  const projectName = current.slice(0, colonIndex);
  const targetPrefix = current.slice(colonIndex + 1);
  return getTargetNamesForProject(targetPrefix, projectName).map(
    (target) => `${projectName}:${target}`
  );
}

/**
 * Locates the `package.json` for a plugin, checking `node_modules` first and
 * then any matching workspace-local project. Returns `null` if not found.
 */
function findPluginPackageJsonPath(pluginName: string): string | null {
  const nodeModulesPath = join(
    workspaceRoot,
    'node_modules',
    pluginName,
    'package.json'
  );
  if (existsSync(nodeModulesPath)) {
    return nodeModulesPath;
  }

  const graph = safeReadProjectGraph();
  const node = graph?.nodes?.[pluginName];
  const root = node?.data?.root;
  if (root) {
    const localPath = join(workspaceRoot, root, 'package.json');
    if (existsSync(localPath)) {
      return localPath;
    }
  }

  return null;
}

/**
 * Reads and parses a plugin's `package.json`, returning `null` when it is
 * missing or malformed.
 */
function readPluginPackageJson(pluginName: string): any | null {
  const packageJsonPath = findPluginPackageJsonPath(pluginName);
  if (!packageJsonPath) {
    return null;
  }
  try {
    return JSON.parse(readFileSync(packageJsonPath, 'utf-8'));
  } catch {
    return null;
  }
}

/**
 * Returns true if the plugin declares a `generators` (or `schematics`) field.
