 * registering each interesting option under its canonical name AND every
 * yargs-declared alias, all sharing the same handler reference.
 */
function buildFlagCompletions(
  commandName: string,
  interestingOptions: string[]
): Record<string, CompletionFn> {
  const handlers = getNxCommandHandlers();
  const command = handlers[commandName];
  const introspected = command
    ? introspectBuilder((command as any).builder)
    : null;
  const aliases = introspected?.aliases ?? new Map<string, string[]>();

  const flags: Record<string, CompletionFn> = {};
  for (const canonical of interestingOptions) {
    const handler = OPTION_HANDLERS[canonical];
    if (!handler) {
      continue;
