 * with the given prefix.
 */
function getAddPackageCompletions(current: string): string[] {
  let packageJson: any;
  try {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    packageJson = require('nx/package.json');
  } catch {
    return [];
  }

  const packageGroup: Array<string | { package: string; version: string }> =
    packageJson['nx-migrations']?.packageGroup ?? [];

  return packageGroup
    .map((entry) => (typeof entry === 'string' ? entry : entry.package))
    .filter((name) => name.startsWith('@nx/') && name.startsWith(current));
